begin;
set local role postgres;
create extension if not exists pgtap with schema extensions;
set local search_path=pgtap,extensions,public;
select plan(31);

select has_table('public','offline_devices','offline devices table exists');
select has_table('public','offline_sync_events','offline sync audit table exists');
select has_column('public','pos_sales','originated_offline','sale records offline origin');
select has_column('public','pos_sales','offline_device_id','sale records device');
select has_column('public','pos_sales','local_transaction_id','sale records local reference');
select has_column('public','pos_sales','local_created_at','sale records device timestamp');
select has_column('public','pos_sales','server_received_at','sale records server timestamp');
select has_column('public','pos_sales','offline_request_hash','sale records immutable replay hash');
select has_function('public','register_offline_device',array['uuid','uuid','uuid','uuid','text','text'],'device registration RPC exists');
select has_function('public','manage_offline_device',array['uuid','uuid','text','text'],'device management RPC exists');
select has_function('public','update_offline_settings',array['uuid','boolean','text','text','boolean','boolean','boolean','integer','integer'],'offline policy RPC exists');
select has_function('public','replay_offline_pos_sale',array['uuid','uuid','uuid','timestamp with time zone','uuid','uuid','jsonb','jsonb','numeric','numeric','text','uuid'],'explicit POS replay RPC exists');
select has_function('public','record_offline_sync_failure',array['uuid','uuid','uuid','text','text'],'sync audit RPC exists');
select is((select count(*)::integer from public.permissions where code like 'offline.%'),7,'all offline capabilities exist');
select is((select count(*)::integer from pg_indexes where schemaname='public' and indexname='pos_sales_offline_reference_unique'),1,'device local reference uniqueness exists');
select is((select relrowsecurity from pg_class where oid='public.offline_devices'::regclass),true,'device RLS enabled');
select is((select relforcerowsecurity from pg_class where oid='public.offline_devices'::regclass),true,'device RLS forced');
select is((select relrowsecurity from pg_class where oid='public.offline_sync_events'::regclass),true,'sync event RLS enabled');

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at) values
('00000000-0000-4000-8000-00000000800a','00000000-0000-0000-0000-000000000000','authenticated','authenticated','offline-owner@example.test','',now(),now(),now()),
('00000000-0000-4000-8000-00000000800b','00000000-0000-0000-0000-000000000000','authenticated','authenticated','offline-outsider@example.test','',now(),now(),now());
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000800a","role":"authenticated"}',true);
select lives_ok($$select public.create_organization('Offline Test','offline-test','GB','GBP','Europe/London')$$,'offline tenant bootstraps');
set local role postgres;
select set_config('x.org',(select id::text from public.organizations where slug='offline-test'),true);
select set_config('x.business',(select id::text from public.businesses where organization_id=current_setting('x.org')::uuid limit 1),true);
insert into public.branches(id,organization_id,business_id,name,code,status,timezone,created_by) values('00000000-0000-4000-8000-000000008101',current_setting('x.org')::uuid,current_setting('x.business')::uuid,'Offline Branch','OFF1','active','Europe/London','00000000-0000-4000-8000-00000000800a');
insert into public.warehouses(id,organization_id,branch_id,business_id,name,code,warehouse_type,status,is_default,created_by) values('00000000-0000-4000-8000-000000008102',current_setting('x.org')::uuid,'00000000-0000-4000-8000-000000008101',current_setting('x.business')::uuid,'Offline Shop','OFFSHOP','SHOP_FLOOR','active',true,'00000000-0000-4000-8000-00000000800a');
select set_config('x.location',(select id::text from public.storage_locations where warehouse_id='00000000-0000-4000-8000-000000008102' and location_type='ROOT'),true);
insert into public.customers(id,organization_id,customer_code,customer_type,display_name,default_currency,created_by) values('00000000-0000-4000-8000-000000008104',current_setting('x.org')::uuid,'WALK-IN','INDIVIDUAL','Walk-in Customer','GBP','00000000-0000-4000-8000-00000000800a');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000800a","role":"authenticated"}',true);
select set_config('x.account',(select public.create_payment_account(current_setting('x.org')::uuid,'00000000-0000-4000-8000-000000008101','TILL','Offline Till','CASH','GBP','POS till')::text),true);
select lives_ok(format($q$select public.create_pos_terminal('%s','00000000-0000-4000-8000-000000008101','OFF1','Offline Till','00000000-0000-4000-8000-000000008102','%s','00000000-0000-4000-8000-000000008104','%s','80MM','Thank you')$q$,current_setting('x.org'),current_setting('x.location'),current_setting('x.account')),'authorized owner creates offline terminal');
select set_config('x.terminal',(select id::text from public.pos_terminals where organization_id=current_setting('x.org')::uuid and terminal_code='OFF1'),true);
select lives_ok(format($q$select public.register_offline_device('%s','00000000-0000-4000-8000-000000008101','%s','00000000-0000-4000-8000-000000008201','Counter tablet','8.0.0')$q$,current_setting('x.org'),current_setting('x.terminal')),'authorized device registration succeeds');
select set_config('x.device',(select id::text from public.offline_devices where organization_id=current_setting('x.org')::uuid and device_identifier='00000000-0000-4000-8000-000000008201'),true);
select is((select branch_id from public.offline_devices where id=current_setting('x.device')::uuid),'00000000-0000-4000-8000-000000008101'::uuid,'device is bound to branch');
select is((select terminal_id from public.offline_devices where id=current_setting('x.device')::uuid),current_setting('x.terminal')::uuid,'device is bound to terminal');
select is((select status from public.offline_devices where id=current_setting('x.device')::uuid),'ACTIVE','device starts active');
select is((select public.register_offline_device(current_setting('x.org')::uuid,'00000000-0000-4000-8000-000000008101',current_setting('x.terminal')::uuid,'00000000-0000-4000-8000-000000008201','Counter tablet','8.0.0')),current_setting('x.device')::uuid,'duplicate registration returns same device');
select lives_ok(format($q$select public.manage_offline_device('%s','%s','Counter tablet','REVOKED')$q$,current_setting('x.org'),current_setting('x.device')),'authorized manager revokes device');
select is((select status from public.offline_devices where id=current_setting('x.device')::uuid),'REVOKED','device revocation persists');
select throws_ok(format($q$select public.register_offline_device('%s','00000000-0000-4000-8000-000000008101','%s','00000000-0000-4000-8000-000000008201','Counter tablet','8.0.0')$q$,current_setting('x.org'),current_setting('x.terminal')),'42501','SYNC_TERMINAL_REVOKED','revoked device cannot register again');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000800b","role":"authenticated"}',true);
select throws_ok(format($q$select public.register_offline_device('%s','00000000-0000-4000-8000-000000008101','%s',gen_random_uuid(),'Outsider','8.0.0')$q$,current_setting('x.org'),current_setting('x.terminal')),'42501','PERMISSION_DENIED','cross-tenant outsider cannot register a device');
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select throws_ok(format($q$select public.register_offline_device('%s','00000000-0000-4000-8000-000000008101','%s',gen_random_uuid(),'Anonymous','8.0.0')$q$,current_setting('x.org'),current_setting('x.terminal')),'42501','permission denied for function register_offline_device','anonymous device identifier cannot authorize');
set local role postgres;
select is((select count(*)::integer from public.audit_events where organization_id=current_setting('x.org')::uuid and action like 'offline.device.%'),3,'initial, repeated registration, and revocation are audited');
select * from finish();
rollback;
